#include <stdio.h>
#include <stdbool.h>

#define SIZE 5

/* ---------- Stack: last in, first out ---------- */
int stack[SIZE];
int top = -1;

bool push(int value) {
    if (top == SIZE - 1) {
        printf("Stack overflow! Can't push %d\n", value);
        return false;
    }
    stack[++top] = value;
    return true;
}

bool pop(int *value) {
    if (top == -1) {
        printf("Stack underflow! Nothing to pop\n");
        return false;
    }
    *value = stack[top--];
    return true;
}

/* ---------- Queue: first in, first out (circular) ---------- */
int queue[SIZE];
int front = 0, count = 0;

bool enqueue(int value) {
    if (count == SIZE) {
        printf("Queue full! Can't add %d\n", value);
        return false;
    }
    int rear = (front + count) % SIZE;
    queue[rear] = value;
    count++;
    return true;
}

bool dequeue(int *value) {
    if (count == 0) {
        printf("Queue empty! Nobody to remove\n");
        return false;
    }
    *value = queue[front];
    front = (front + 1) % SIZE;
    count--;
    return true;
}

int main(void) {
    int v;

    for (int i = 1; i <= 6; i++)
        push(i * 10);
    while (pop(&v))
        printf("Popped %d\n", v);

    enqueue(10); enqueue(20); enqueue(30);
    dequeue(&v);
    printf("Dequeued %d\n", v);
    enqueue(40);
    while (dequeue(&v))
        printf("Dequeued %d\n", v);

    return 0;
}

