#include <stdio.h>
#include <stdbool.h>

#define SIZE 100

char stack[SIZE];
int top = -1;

bool matches(char open, char close) {
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

bool balanced(const char *s) {
    top = -1;
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (top == SIZE - 1)
                return false;
            stack[++top] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == -1 || !matches(stack[top--], c))
                return false;
        }
    }
    return top == -1;
}

int main(void) {
    const char *tests[] = {"{a[i] = (b + c);}", "(x + y]", "((1 + 2)"};
    for (int i = 0; i < 3; i++)
        printf("%-20s %s\n", tests[i], balanced(tests[i]) ? "balanced" : "NOT balanced");
    return 0;
}

